// The only module that imports @earendil-works/*. It binds the engine port to pi's Agent, resolves models, and
// carries engine records inside pi's transcript. Every plugin rule lives behind the Engine port.

import { Agent, type AgentMessage, type AgentTool, type StreamFn } from '@earendil-works/pi-agent-core'
import { envApiKeyAuth, validateToolArguments, type Api, type AssistantMessage, type Message, type Model, type TSchema } from '@earendil-works/pi-ai'
import { openAICompletionsApi } from '@earendil-works/pi-ai/api/openai-completions.lazy'
import { createModels, createProvider } from '@earendil-works/pi-ai/models'
import { builtinModels } from '@earendil-works/pi-ai/providers/all'
import { parseCatalog } from './catalog.ts'
import { createEngine, type Engine, type Turn, type Validate } from './engine.ts'
import type { JsonObject, JsonValue, ToolResult } from './plugin.ts'
import type { EngineRecord, ModelSpec, RunResult, Session, SessionEvent, SessionOptions, Transcript } from './session.ts'

/** Engine records ride in pi's transcript under their own role; convertToLlm drops them. */
interface RecordMessage {
  readonly role: 'aigent'
  readonly record: EngineRecord
  readonly timestamp: number
}

declare module '@earendil-works/pi-agent-core' {
  interface CustomAgentMessages {
    aigent: RecordMessage
  }
}

export interface ResolvedModel {
  readonly model: Model<Api>
  readonly streamFn: StreamFn
  /** The model's API key under its env var name, so it is redacted like any host secret. */
  readonly secrets: Readonly<Record<string, string>>
}

const TRANSCRIPT_FORMAT = 'aigent-transcript/1'

export async function createSession(options: SessionOptions): Promise<Session> {
  return startSession(options, await resolveModel(options.model))
}

/** `createSession` with the model already resolved. The adapter's offline test passes pi's faux provider here. */
export async function startSession(options: SessionOptions, resolved: ResolvedModel): Promise<Session> {
  if (options.systemPrompt !== undefined && options.transcript !== undefined) throw new Error('pass systemPrompt or transcript, not both')
  const resumed = options.transcript && parseTranscript(options.transcript)
  const listeners = new Set<(event: SessionEvent) => void>()
  const writeLog = options.log ?? ((line: string) => console.error(`[aigent] ${line}`))
  // Nobody can subscribe before createSession returns, so this never runs before `engine` exists.
  const dispatch = (event: SessionEvent): void => {
    for (const listener of listeners) {
      try {
        listener(redactJson(event, engine.redact))
      } catch (error) {
        writeLog(engine.redact(`listener threw: ${messageOf(error)}`))
      }
    }
  }

  const secrets = { ...options.secrets, ...resolved.secrets }
  const engine: Engine = await createEngine({
    catalog: parseCatalog(options.plugins),
    toolMode: options.toolMode ?? 'native',
    start: resumed ? { kind: 'resume', records: resumed.records } : { kind: 'fresh', systemPrompt: options.systemPrompt ?? '' },
    enabled: options.enabled ?? [],
    secrets,
    maxTurns: options.maxTurns ?? 25,
    hookTimeoutMs: options.hookTimeoutMs ?? 10_000,
    validate: piValidate,
    emit: dispatch,
    log: writeLog,
  })

  const agentTools = (): AgentTool[] =>
    engine.tools().map((spec) => ({
      name: spec.name,
      label: spec.name,
      description: spec.description,
      parameters: spec.parameters as unknown as TSchema,
      execute: async (toolCallId, params, signal) => {
        const result = await engine.callTool({ id: toolCallId, name: spec.name, args: params as JsonObject }, signal ?? new AbortController().signal)
        return toAgentResult(result)
      },
    }))
  const wrap = (record: EngineRecord): RecordMessage => ({ role: 'aigent', record, timestamp: Date.now() })

  // The last assistant message finishTurn reported, so a run pi ends without calling it still gets its turn.
  let reported: AgentMessage | undefined
  const agent = new Agent({
    initialState: { model: resolved.model, systemPrompt: engine.systemPrompt, tools: agentTools(), messages: resumed?.messages ?? [] },
    streamFn: resolved.streamFn,
    convertToLlm: (messages) => messages.filter((m): m is Message => m.role !== 'aigent'),
    // Runs before pi declares tool changes, so the new declarations land ahead of the request that can use them.
    prepareNextTurnWithContext: (turn) => ({ context: { ...turn.context, tools: agentTools() }, messages: engine.takeRecords().map(wrap) }),
    finishTurn: async (turn) => {
      reported = turn.message
      return (await engine.endTurn(toTurn(turn.message))) === 'stop' ? { action: 'end' } : undefined
    },
  })
  const text = holdBack(Math.max(0, ...Object.values(secrets).map((v) => v.length)), engine.redact, (delta) => dispatch({ type: 'text', delta }))
  agent.subscribe((event) => {
    if (event.type === 'message_update' && event.assistantMessageEvent.type === 'text_delta') text.push(event.assistantMessageEvent.delta)
    // pi ends every assistant message this way, whether it finished, errored or was aborted.
    else if (event.type === 'message_end') text.flush()
  })

  const flush = (): void => {
    const records = engine.takeRecords()
    if (records.length > 0) agent.state.messages = [...agent.state.messages, ...records.map(wrap)]
  }
  flush()

  let running: AbortController | undefined
  let closed: Promise<void> | undefined

  return {
    async prompt(text, { signal } = {}) {
      if (closed) throw new Error('session is closed')
      if (running) throw new Error('a prompt is already running')
      const controller = new AbortController()
      running = controller
      const runSignal = signal ? AbortSignal.any([signal, controller.signal]) : controller.signal
      const onAbort = () => agent.abort()
      runSignal.addEventListener('abort', onAbort, { once: true })
      try {
        const content = await engine.beginPrompt(text, runSignal)
        agent.state.tools = agentTools()
        reported = undefined
        const run = agent.prompt([...engine.takeRecords().map(wrap), { role: 'user', content, timestamp: Date.now() }])
        // agent.prompt registers its run synchronously, so an abort that fired before it started still lands.
        if (runSignal.aborted) agent.abort()
        await run
        const last = agent.state.messages.at(-1)
        if (last?.role === 'assistant' && last !== reported) await engine.endTurn(toTurn(last))
        flush()
        return engine.endRun()
      } finally {
        runSignal.removeEventListener('abort', onAbort)
        running = undefined
      }
    },

    async enable(name) {
      await engine.enable(name)
      if (!running) flush()
    },

    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },

    transcript() {
      const messages = JSON.parse(JSON.stringify(agent.state.messages)) as AgentMessage[]
      return { format: TRANSCRIPT_FORMAT, messages: messages.map((m) => exportMessage(m, engine.redact)) as unknown as JsonValue[] }
    },

    close() {
      closed ??= (async () => {
        running?.abort()
        await agent.waitForIdle()
        flush()
        await engine.close()
      })()
      return closed
    },
  }
}

async function resolveModel(spec: ModelSpec): Promise<ResolvedModel> {
  if (spec.kind === 'openai-compatible') {
    const key = process.env[spec.apiKeyEnv]
    if (!key) throw new Error(`${spec.apiKeyEnv} is not set`)
    const models = createModels()
    models.setProvider(
      createProvider({
        id: 'openai-compatible',
        baseUrl: spec.baseUrl,
        auth: { apiKey: envApiKeyAuth(spec.apiKeyEnv, [spec.apiKeyEnv]) },
        models: [
          {
            id: spec.id,
            name: spec.id,
            api: 'openai-completions',
            baseUrl: spec.baseUrl,
            provider: 'openai-compatible',
            type: 'chat',
            reasoning: spec.reasoning ?? true,
            input: ['text'],
            cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
            contextWindow: spec.contextWindow ?? 131_072,
            maxTokens: spec.maxTokens ?? 8192,
          },
        ],
        api: openAICompletionsApi(),
      }),
    )
    const model = models.getModel('openai-compatible', spec.id)
    if (!model) throw new Error(`model ${spec.id} did not register`)
    return { model, streamFn: (m, context, o) => models.streamSimple(m, context, o), secrets: { [spec.apiKeyEnv]: key } }
  }
  const models = builtinModels()
  const model = models.getModel(spec.provider, spec.id)
  if (!model) throw new Error(`unknown model ${spec.provider}/${spec.id}`)
  const key = (await models.getAuth(model))?.auth.apiKey
  return { model, streamFn: (m, context, o) => models.streamSimple(m, context, o), secrets: key ? { MODEL_API_KEY: key } : {} }
}

const piValidate: Validate = (schema, args, name) => {
  try {
    const tool = { name, description: '', parameters: schema as unknown as TSchema }
    const valid: JsonObject = validateToolArguments(tool, { type: 'toolCall', id: '', name, arguments: args as Record<string, never> })
    return { ok: true, args: valid }
  } catch (error) {
    return { ok: false, error: messageOf(error) }
  }
}

function toAgentResult(result: ToolResult) {
  return { content: result.content.map((c) => ({ ...c })), details: undefined, ...(result.isError ? { isError: true } : {}) }
}

function toTurn(message: AssistantMessage): Turn {
  if (message.stopReason === 'aborted') return { kind: 'aborted' }
  if (message.stopReason === 'error') return { kind: 'error', message: message.errorMessage ?? 'model request failed' }
  return { kind: 'ok', text: message.content.flatMap((c) => (c.type === 'text' ? [c.text] : [])).join('') }
}

/** Resume boundary: the format tag and a role on every message. Records are parsed by the engine. */
function parseTranscript(transcript: Transcript): { readonly messages: AgentMessage[]; readonly records: readonly unknown[] } {
  if (transcript?.format !== TRANSCRIPT_FORMAT || !Array.isArray(transcript.messages)) throw new Error(`not an ${TRANSCRIPT_FORMAT} transcript`)
  const messages = transcript.messages.map((m, i) => {
    if (typeof m !== 'object' || m === null || Array.isArray(m) || typeof (m as { role?: unknown }).role !== 'string') {
      throw new Error(`transcript message ${i} has no role`)
    }
    return m as unknown as AgentMessage
  })
  return { messages, records: messages.flatMap((m) => (m.role === 'aigent' ? [m.record as unknown] : [])) }
}

/** Text fields only. Opaque provider fields such as thinking and text signatures pass through untouched. */
function exportMessage(message: AgentMessage, redact: (text: string) => string): AgentMessage {
  const text = <T extends { type: string }>(c: T): T => (c.type === 'text' ? { ...c, text: redact((c as unknown as { text: string }).text) } : c)
  switch (message.role) {
    case 'system':
      return {
        ...message,
        content: typeof message.content === 'string' ? redact(message.content) : message.content.map(text),
        ...(message.sections ? { sections: Object.fromEntries(Object.entries(message.sections).map(([k, v]) => [k, v === null ? v : redact(v)])) } : {}),
      }
    case 'user':
      return { ...message, content: typeof message.content === 'string' ? redact(message.content) : message.content.map(text) }
    case 'assistant':
      return {
        ...message,
        content: message.content.map((c) =>
          c.type === 'text' ? text(c) : c.type === 'thinking' ? { ...c, thinking: redact(c.thinking) } : { ...c, arguments: redactJson(c.arguments, redact) },
        ),
        ...(message.errorMessage ? { errorMessage: redact(message.errorMessage) } : {}),
      }
    case 'toolResult':
      return { ...message, content: message.content.map(text) }
    case 'aigent': {
      const { record } = message
      if (record.kind === 'denied') return { ...message, record: { ...record, reason: redact(record.reason) } }
      if (record.kind === 'pending') return { ...message, record: { ...record, text: redact(record.text) } }
      return message
    }
    default:
      return message satisfies never
  }
}

/**
 * Redacting each delta alone lets a listener rejoin a secret split across deltas. Any secret that could still be
 * completing starts within the last `longest - 1` characters, so those wait for more text or the message's end.
 */
function holdBack(longest: number, redact: (text: string) => string, emit: (delta: string) => void) {
  let held = ''
  return {
    push(delta: string): void {
      held = redact(held + delta)
      let cut = held.length - Math.max(0, longest - 1)
      // Never strand half of a surrogate pair at the end of a delta.
      if (cut > 0 && /[\uD800-\uDBFF]/.test(held[cut - 1]!)) cut -= 1
      if (cut <= 0) return
      emit(held.slice(0, cut))
      held = held.slice(cut)
    },
    flush(): void {
      if (held) emit(held)
      held = ''
    },
  }
}

/** Deep-redacts strings in our own JSON-shaped values. Image data is left alone. */
function redactJson<T>(value: T, redact: (text: string) => string): T {
  if (typeof value === 'string') return redact(value) as T
  if (Array.isArray(value)) return value.map((v) => redactJson(v, redact)) as T
  if (typeof value !== 'object' || value === null) return value
  const image = (value as { type?: unknown }).type === 'image'
  return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, image && k === 'data' ? v : redactJson(v, redact)])) as T
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

// The engine core: the record log and everything derived from it, the core plugin, enabling, the tool pipeline,
// gates, redaction, stop conditions and the run outcome. Knows nothing about pi; any loop drives it through Engine.

import { CORE, qualify, type Catalog, type PluginName, type ToolName } from './catalog.ts'
import type {
  Content,
  Hooks,
  JsonObject,
  JsonSchema,
  MaybePromise,
  Plugin,
  Tool,
  ToolCallSnapshot,
  ToolResult,
  ToolResultSnapshot,
} from './plugin.ts'
import type { EngineRecord, RunResult, SessionEvent, ToolMode } from './session.ts'

export interface ToolSpec {
  readonly name: ToolName
  readonly description: string
  readonly parameters: JsonSchema
}

/** A call as the loop hands it over. For a declared tool, `args` already passed validation. */
export interface ToolCall {
  readonly id: string
  readonly name: string
  readonly args: JsonObject
}

/** One completed model turn, as the loop saw it. */
export type Turn = { readonly kind: 'ok'; readonly text: string } | { readonly kind: 'error'; readonly message: string } | { readonly kind: 'aborted' }

/** Validates and coerces `args` against `schema`, as the loop does for declared tools. */
export type Validate = (schema: JsonSchema, args: JsonObject, tool: string) => { readonly ok: true; readonly args: JsonObject } | { readonly ok: false; readonly error: string }

export interface EngineOptions {
  readonly catalog: Catalog
  readonly toolMode: ToolMode
  /** Fresh sessions build a system prompt. Resumed ones replay the records a transcript carried, running no hooks. */
  readonly start: { readonly kind: 'fresh'; readonly systemPrompt: string } | { readonly kind: 'resume'; readonly records: readonly unknown[] }
  /** Enabled at creation. On resume, names already enabled are skipped and the rest are delivered like a host enable. */
  readonly enabled: readonly string[]
  readonly secrets: Readonly<Record<string, string>>
  readonly maxTurns: number
  readonly hookTimeoutMs: number
  readonly validate: Validate
  readonly emit: (event: SessionEvent) => void
  readonly log: (line: string) => void
}

/**
 * The port. Per prompt a loop calls: beginPrompt, then per model request tools() and, after the turn,
 * callTool* and endTurn, then takeRecords to append new records to its transcript; endRun once the run stops.
 * `enable` may be called at any time, including mid-run.
 */
export interface Engine {
  /** The leading system prompt of a fresh session. Undefined on resume, where the transcript already has one. */
  readonly systemPrompt: string | undefined
  /** Declarations for the next request, in stable order. */
  tools(): readonly ToolSpec[]
  /** Records appended since the last call. */
  takeRecords(): readonly EngineRecord[]
  /** Starts a run and returns the user message text: the prompt, then queued enable text, catalog drift and onUserPrompt text. */
  beginPrompt(text: string, signal: AbortSignal): Promise<string>
  /** Resolve, unwrap, gate, execute, redact, observe. Never rejects. */
  callTool(call: ToolCall, signal: AbortSignal): Promise<ToolResult>
  /** Runs onTurnEnd observers, then the stop conditions. */
  endTurn(turn: Turn): Promise<'continue' | 'stop'>
  endRun(): RunResult
  /** Host enable. Rejects on an unknown name. */
  enable(name: string): Promise<void>
  redact(text: string): string
  /** Fires onSessionEnd once and rejects later prompts. */
  close(): Promise<void>
}

type EnabledRecord = Extract<EngineRecord, { kind: 'enabled' }>
type StopReason = 'aborted' | 'max_turns'

interface Run {
  readonly signal: AbortSignal
  turns: number
  last: Turn | undefined
  stoppedBy: StopReason | undefined
  calls: ToolResultSnapshot[]
}

interface Entry {
  readonly name: ToolName
  readonly plugin: PluginName
  readonly tool: Tool
}

type Settled<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly reason: string }

const CALL_TOOL: ToolSpec = {
  name: qualify(CORE, 'call_tool'),
  description: 'Call a tool of a plugin enabled during this conversation. Its name and parameters are listed where it was enabled.',
  parameters: {
    type: 'object',
    properties: {
      tool: { type: 'string', description: 'Full tool name, <plugin>__<tool>' },
      args: { type: 'object', description: "Arguments matching the tool's parameters" },
    },
    required: ['tool'],
    additionalProperties: false,
  },
}

export async function createEngine(options: EngineOptions): Promise<Engine> {
  const { catalog, toolMode, validate, emit } = options
  const redact = makeRedactor(options.secrets)
  const log = (line: string) => options.log(redact(line))

  const records: EngineRecord[] = []
  const byKind = {
    enabled: new Map<PluginName, EnabledRecord>(),
    catalog: [] as Extract<EngineRecord, { kind: 'catalog' }>[],
    undelivered: [] as string[],
  }
  let taken = 0
  const index = (record: EngineRecord): void => {
    records.push(record)
    switch (record.kind) {
      case 'enabled':
        byKind.enabled.set(record.plugin, record)
        return
      case 'catalog':
        byKind.catalog.push(record)
        return
      case 'pending':
        byKind.undelivered.push(record.text)
        return
      case 'delivered':
        byKind.undelivered = []
        return
      case 'denied':
        return
      default:
        return record satisfies never
    }
  }
  const append = (record: EngineRecord): void => {
    index(record)
    emit({ type: 'record', record })
  }

  const closing = new AbortController()
  let ended: Promise<void> | undefined
  let run: Run = { signal: new AbortController().signal, turns: 0, last: undefined, stoppedBy: undefined, calls: [] }
  let totalTurns = 0
  let hookPhase: Promise<unknown> = Promise.resolve()

  const enabled = (): PluginName[] => [...byKind.enabled.keys()]
  const pluginOf = (name: PluginName): Plugin => catalog.plugins.get(name)!
  const activePlugins = (): Plugin[] => enabled().map(pluginOf)

  /** In the first request's tool list: enabled at creation, or a dependency pulled in by such a plugin. */
  const isInitial = (name: PluginName): boolean => {
    const cause = byKind.enabled.get(name)?.cause
    return cause === 'initial' || (typeof cause === 'object' && byKind.enabled.get(cause.dependencyOf)?.cause === 'initial')
  }
  const declaresNatively = (name: PluginName): boolean => toolMode === 'native' || isInitial(name)

  const catalogText = (): string => {
    const lines = [...catalog.plugins].filter(([name]) => !byKind.enabled.has(name)).map(([name, p]) => `- ${name}: ${p.description}`)
    const body = lines.length > 0 ? `Plugins you can enable with core__enable_plugin:\n${lines.join('\n')}` : 'Every available plugin is enabled.'
    return redact(`<plugin-catalog>\n${body}\n</plugin-catalog>`)
  }

  const pluginText = (name: PluginName, added: string | undefined): string => {
    const plugin = pluginOf(name)
    const tools = (plugin.tools ?? []).map((tool) => ({ name: qualify(name, tool.name), tool }))
    const parts = [plugin.instructions, added]
    if (plugin.skills?.length) {
      parts.push(`Skills (load with core__load_skill):\n${plugin.skills.map((s) => `- ${name}__${s.name}: ${s.description}`).join('\n')}`)
    }
    if (tools.length > 0 && declaresNatively(name)) parts.push(`Tools: ${tools.map((t) => t.name).join(', ')}`)
    else if (tools.length > 0) {
      const lines = tools.map((t) => `- ${t.name}: ${t.tool.description}\n  Parameters: ${JSON.stringify(t.tool.parameters)}`)
      parts.push(`Tools (call with ${CALL_TOOL.name}):\n${lines.join('\n')}`)
    }
    return redact(`<plugin name="${name}">\n${parts.filter((p) => p?.trim()).join('\n\n')}\n</plugin>`)
  }

  /** Calls one hook under the timeout, never rejecting. The hook's signal fires on timeout, close or `extra`. */
  async function settle<T>(call: (signal: AbortSignal) => MaybePromise<T>, extra: readonly AbortSignal[]): Promise<Settled<T>> {
    // A ref'd timer, unlike AbortSignal.timeout, so a hook that never settles still gets its verdict.
    const timeout = new AbortController()
    const timer = setTimeout(() => timeout.abort(new Error('timeout')), options.hookTimeoutMs)
    const signal = AbortSignal.any([timeout.signal, ...extra])
    let onAbort = () => {}
    try {
      const value = await new Promise<T>((resolve, reject) => {
        onAbort = () => reject(signal.reason)
        if (signal.aborted) onAbort()
        signal.addEventListener('abort', onAbort, { once: true })
        Promise.resolve()
          .then(() => call(signal))
          .then(resolve, reject)
      })
      return { ok: true, value }
    } catch (error) {
      return { ok: false, reason: timeout.signal.aborted ? `timed out after ${options.hookTimeoutMs}ms` : messageOf(error) }
    } finally {
      clearTimeout(timer)
      signal.removeEventListener('abort', onAbort)
    }
  }

  /** Runs one hook across the plugins that define it, concurrently, returning results in plugin order. */
  function each<T>(
    plugins: readonly Plugin[],
    hook: keyof Hooks,
    invoke: (hooks: Hooks, signal: AbortSignal) => MaybePromise<T>,
    extra: readonly AbortSignal[] = [closing.signal],
  ): Promise<{ readonly plugin: PluginName; readonly settled: Settled<T> }[]> {
    const hooked = plugins.filter((p) => p.hooks?.[hook])
    return Promise.all(hooked.map(async (p) => ({ plugin: p.name as PluginName, settled: await settle((s) => invoke(p.hooks!, s), extra) })))
  }

  const logFailures = (hook: keyof Hooks, results: readonly { plugin: PluginName; settled: Settled<unknown> }[]): void => {
    for (const { plugin, settled } of results) if (!settled.ok) log(`plugin "${plugin}" ${hook} failed: ${settled.reason}`)
  }

  const addedText = (hook: keyof Hooks, results: readonly { plugin: PluginName; settled: Settled<string | undefined> }[]): string[] => {
    logFailures(hook, results)
    return results.flatMap(({ settled }) => (settled.ok && typeof settled.value === 'string' && settled.value.trim() ? [settled.value] : []))
  }

  async function runGates(call: ToolCallSnapshot, signal: AbortSignal): Promise<{ plugin: PluginName; reason: string }[]> {
    const results = await each(activePlugins(), 'beforeToolCall', (h, s) => h.beforeToolCall!(call, s), [closing.signal, signal])
    return results.flatMap(({ plugin, settled }) => {
      if (!settled.ok) return [{ plugin, reason: redact(`gate failed: ${settled.reason}`) }]
      const verdict: unknown = settled.value
      if (verdict === 'allow') return []
      const deny = typeof verdict === 'object' && verdict !== null ? (verdict as { deny?: unknown }).deny : undefined
      return [{ plugin, reason: typeof deny === 'string' ? redact(deny) : 'gate returned no verdict' }]
    })
  }

  /**
   * Commits the `enabled` records before the first await, so a racing enable sees the plugin enabled and adds
   * nothing. onEnable phases run through one promise chain so their text lands in enable order.
   */
  async function enablePlugin(name: PluginName, cause: 'initial' | 'host' | 'model'): Promise<{ added: PluginName[]; text: string }> {
    const added = catalog.closures.get(name)!.filter((n) => !byKind.enabled.has(n))
    for (const n of added) append({ kind: 'enabled', plugin: n, cause: n === name ? cause : { dependencyOf: name } })
    if (added.length === 0) return { added, text: '' }
    const phase = hookPhase.then(async () => {
      const blocks: string[] = []
      for (const n of added) {
        const snapshot = deepFreeze({ plugin: n as string, cause: byKind.enabled.get(n)!.cause, enabled: enabled() as string[] })
        const [extra] = addedText('onEnable', await each([pluginOf(n)], 'onEnable', (h, s) => h.onEnable!(snapshot, s)))
        blocks.push(pluginText(n, extra))
      }
      return blocks.join('\n\n')
    })
    hookPhase = phase.catch(() => {})
    return { added, text: await phase }
  }

  const parseName = (name: string): PluginName => {
    const parsed = catalog.pluginName(name)
    if (!parsed) throw new Error(`unknown plugin "${name}"`)
    return parsed
  }

  const core: Plugin = {
    name: CORE,
    description: 'Enables plugins and loads skills.',
    tools: [
      {
        name: 'enable_plugin',
        description: 'Enable a plugin from the catalog. Its tools and skills are usable from your next step.',
        parameters: {
          type: 'object',
          properties: { name: { type: 'string', description: 'Plugin name from the catalog' } },
          required: ['name'],
          additionalProperties: false,
        },
        async execute(args) {
          const name = catalog.pluginName(String(args.name))
          if (!name) return errorResult(`No plugin named "${String(args.name)}". Available: ${[...catalog.plugins.keys()].join(', ')}.`)
