/** Transcript boundary: a malformed or unknown record throws, because guessing would rebuild a different engine. */
function parseRecord(value: unknown, catalog: Catalog, registry: ReadonlyMap<string, { readonly name: ToolName }>): EngineRecord {
  const fail = (why: string): never => {
    throw new Error(`transcript record ${JSON.stringify(value)}: ${why}`)
  }
  if (typeof value !== 'object' || value === null) return fail('not an object')
  const r = value as Record<string, unknown>
  const plugin = (field: unknown): PluginName =>
    (typeof field === 'string' && catalog.pluginName(field)) || fail(`plugin ${JSON.stringify(field)} is not in the plugin set`)
  switch (r.kind) {
    case 'enabled': {
      const cause = r.cause
      if (cause === 'initial' || cause === 'host' || cause === 'model') return { kind: 'enabled', plugin: plugin(r.plugin), cause }
      if (typeof cause === 'object' && cause !== null && 'dependencyOf' in cause) {
        return { kind: 'enabled', plugin: plugin(r.plugin), cause: { dependencyOf: plugin(cause.dependencyOf) } }
      }
      return fail('unknown cause')
    }
    case 'denied': {
      const tool = typeof r.tool === 'string' ? registry.get(r.tool)?.name : undefined
      if (!tool) return fail('unknown tool')
      if (typeof r.callId !== 'string' || typeof r.reason !== 'string') return fail('missing callId or reason')
      return { kind: 'denied', callId: r.callId, tool, plugin: plugin(r.plugin), reason: r.reason }
    }
    case 'catalog':
      return typeof r.fingerprint === 'string' ? { kind: 'catalog', fingerprint: r.fingerprint } : fail('missing fingerprint')
    case 'pending':
      return typeof r.text === 'string' ? { kind: 'pending', text: r.text } : fail('missing text')
    case 'delivered':
      return { kind: 'delivered' }
